import json,datetime as dt,holidays,calendar,collections
D=json.load(open('/work/audit/derived-b2.json'))
def hol(land,y):
    return holidays.Germany(years=range(y-1,y+3),subdiv=land) if land else holidays.Germany(years=range(y-1,y+3))
def isfree(x,H): return x.weekday()>=5 or x in H
def addm(x,n):
    m=x.month-1+n; y=x.year+m//12; m=m%12+1
    return dt.date(y,m,min(x.day,calendar.monthrange(y,m)[1]))
def fwd(x,n,u,H):
    if u=='days': return x+dt.timedelta(n)
    if u=='weeks': return x+dt.timedelta(7*n)
    if u=='months': return addm(x,n)
    k=0
    while k<n:
        x+=dt.timedelta(1)
        if u=='werktage' and x.weekday()<6 and x not in H: k+=1
        if u=='arbeitstage' and x.weekday()<5 and x not in H: k+=1
    return x
def run(frm,steps,land):
    x=dt.date.fromisoformat(frm); H=hol(land,x.year)
    for s in steps:
        if s['op']=='forward':
            x=fwd(x,s['n'],s['unit'],H)
            if s['shift']:
                while isfree(x,H): x+=dt.timedelta(1)
        elif s['op']=='back':
            c=x
            while fwd(c,s['n'],s['unit'],H)>x: c-=dt.timedelta(1)
            x=c
            if s['shift']:
                while isfree(x,H): x-=dt.timedelta(1)
        elif s['op']=='month_end':
            y=addm(dt.date(x.year,x.month,1),s['n']); x=dt.date(y.year,y.month,calendar.monthrange(y.year,y.month)[1])
            if s['shift']:
                while isfree(x,H): x+=dt.timedelta(1)
    return x.isoformat()
cnt=collections.Counter(); probs=[]
for L,e in sorted(D['letters'].items()):
    facts={f['slot']:f for f in e['facts']}
    for s,v in e['slots'].items():
        cnt[v['status']]+=1
        need={'dated':['date'],'ambiguous':['candidates'],'undatable':['why']}[v['status']]
        for k in need+['status','steps','citations','why']:
            if k not in v: probs.append((L,s,'missing',k))
        if s[0] in 'io' and 'kind' not in v: probs.append((L,s,'kind'))
        f=facts.get(s)
        if not f: probs.append((L,s,'nofact')); continue
        if v['status']=='dated':
            r=run(f['from'],f['steps'],f['land'])
            if r!=v['date']: probs.append((L,s,r,v['date']))
            if f['land'] is None:
                for ld in ['BW','BY','BE','BB','HB','HH','HE','MV','NI','NW','RP','SL','SN','ST','SH','TH']:
                    if run(f['from'],f['steps'],ld)!=r: probs.append((L,s,'land-dep',ld))
        elif v['status']=='ambiguous':
            rs=[run(a['from'],a['steps'],f['land']) for a in f['ambiguous']]
            if sorted(rs)!=sorted(v['candidates']): probs.append((L,s,rs,v['candidates']))
        else:
            if not f.get('undatable'): probs.append((L,s,'undat'))
    for f in e['facts']:
        if f['slot'] not in e['slots'] and f['slot']!='price_change': probs.append((L,'extra fact',f['slot']))
print('problems',probs)
print('letters',len(D['letters']),dict(cnt),'slots',sum(cnt.values()))
